mapper.select:
SELECT 
  FROM act12_journal_map
       LEFT OUTER JOIN act10_repr_account ON (act10_company_id = act12_company_id AND act10_repr_account_cd = act12_repr_account_cd)
 WHERE act12_company_id    = #{companyId}
   AND act12_journal_group = #{journalGroup}
 ORDER BY act12_seq

